def bfs_at_depth(graph, start, target_depth):
    """Find nodes at exactly target_depth from start node using BFS."""
    visited = set([start])
    queue = deque([(start, 0)])
    depth_nodes = defaultdict(set)

    while queue:
        node, depth = queue.popleft()

        if depth == target_depth:
            depth_nodes[depth].add(node)

        if depth < target_depth:
            for neighbor in graph.get(node, []):
                if neighbor not in visited or depth + 1 == target_depth:
                    # We need to track depth, so we allow revisiting at different depths
                    # but we don't want to process same node at same depth twice
                    queue.append((neighbor, depth + 1))
                    visited.add(neighbor)
                    depth_nodes[depth + 1].add(neighbor)

    return sorted(list(depth_nodes[target_depth]))

